const form=document.querySelector('#join-form'),status=document.querySelector('#social-status'),people=document.querySelector('#social-people'),roomInput=document.querySelector('#room-code'),nameInput=document.querySelector('#visitor-name');
const invited=new URL(location.href).searchParams.get('room');let room=/^[a-zA-Z0-9_-]{8,48}$/.test(invited||'')?invited:'winter-plaza',joined=false,busy=false,gesture='',failures=0;roomInput.value=room;
try{nameInput.value=localStorage.getItem('winter-visitor-name')||'';}catch{}
async function request(path,body){const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(8000)});const data=await r.json();if(!r.ok){const e=Error(data.error||'연결을 다시 확인해 주세요.');e.status=r.status;throw e;}return data;}
function showPeople(list){people.replaceChildren();for(const person of list){const li=document.createElement('li');li.textContent=person.name+(person.gesture==='wave'?' · 손 흔드는 중':'');people.append(li);}window.dispatchEvent(new CustomEvent('lab:visitors',{detail:list}));}
form.addEventListener('submit',async e=>{e.preventDefault();if(joined){status.textContent='이미 함께 걷고 있어요. 다른 공간에 가려면 먼저 나와 주세요.';return;}const button=form.querySelector('button');button.disabled=true;status.textContent='같은 공간을 연결하고 있어요…';try{const data=await request('join',{name:nameInput.value,room:roomInput.value});room=data.room;joined=true;failures=0;try{localStorage.setItem('winter-visitor-name',data.name);}catch{}document.querySelector('#leave-room').hidden=false;status.textContent='함께 걷는 중 · 나 1명';window.labSocialJoined=true;await sync();}catch(e){status.textContent=e.message;}finally{button.disabled=false;}});
async function sync(){if(!joined||busy||document.hidden||!window.labPlayerState)return;busy=true;try{const a=window.labAppearance||{},data=await request('presence',{...window.labPlayerState,color:a.fur,accessory:a.accessory,gesture});gesture='';failures=0;showPeople(data.people);status.textContent='함께 걷는 중 · '+data.count+'명';}catch(e){failures++;if(e.status===401){joined=false;window.labSocialJoined=false;showPeople([]);}status.textContent=e.message+(joined?' · 연결을 다시 시도하고 있어요.':'');if(failures>2)showPeople([]);}finally{busy=false;}}
document.querySelector('#leave-room').onclick=async()=>{joined=false;window.labSocialJoined=false;showPeople([]);try{await request('leave',{});}catch{}status.textContent='혼자 느긋하게 걷는 중';document.querySelector('#leave-room').hidden=true;};
document.querySelector('#wave').onclick=()=>{if(!joined){status.textContent='입장한 뒤 인사할 수 있어요.';return;}gesture='wave';window.parkCelebrate?.();sync();};
document.querySelector('#new-room').onclick=()=>{if(joined){status.textContent='현재 공간에서 나온 뒤 새 공간을 만들어 주세요.';return;}room=crypto.randomUUID().replaceAll('-','').slice(0,16);roomInput.value=room;status.textContent='새 초대 공간을 만들었어요. 입장한 뒤 링크를 공유하세요.';};
document.querySelector('#copy-room').onclick=async()=>{const url=new URL(location.href);url.searchParams.set('room',roomInput.value);try{await navigator.clipboard.writeText(url.href);status.textContent='초대 링크를 복사했어요.';}catch{const link=document.querySelector('#invite-url');link.hidden=false;link.value=url.href;link.select();status.textContent='아래 주소를 복사해 주세요.';}};
setInterval(sync,1000);window.addEventListener('pagehide',()=>{if(joined)navigator.sendBeacon('/api/leave','{}');});
